declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();$role=(string)$_SESSION['role'];$uid=(int)$_SESSION['user_id'];$allowed=['teacher','assistant_academic','head_academic','examination_officer','headteacher','sub_director','director'];if(!in_array($role,$allowed,true)){http_response_code(403);exit('Your role cannot access examinations.');}$q=db()->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();if(!$schools){http_response_code(403);exit('No school is linked to your account.');}$schoolId=(int)($_GET['school_id']??$schools[0]['id']);if(!in_array($schoolId,array_map('intval',array_column($schools,'id')),true)){http_response_code(403);exit('That school is outside your access.');}$schoolName='School';foreach($schools as $s)if((int)$s['id']===$schoolId)$schoolName=$s['name'];$csrf=csrf_token();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Examinations · ShuleLite</title><link rel="stylesheet" href="assets/app.css"><script defer src="assets/api.js"></script><script defer src="assets/app.js"></script><script defer src="assets/exams.js"></script></head><body><div class="app-shell"><?php require __DIR__.'/sidebar.php';?><main class="main-area"><header class="topbar"><button class="icon-button menu-toggle" data-menu aria-label="Open navigation" aria-expanded="false">☰</button><div class="crumb">Academics <span>/</span> Examinations</div><div class="top-actions"><span class="role-chip"><?=e(str_replace('_',' ',$role))?></span><div class="user-name"><?=e((string)($_SESSION['name']??'User'))?></div></div></header><div class="page-content exams-page" data-api="api/exams.php" data-school="<?=$schoolId?>" data-user="<?=$uid?>" data-csrf="<?=e($csrf)?>" data-role="<?=e($role)?>"><section class="welcome-row"><div><div class="eyebrow">EXAMINATION WORKFLOW</div><h1>Examinations</h1><p class="muted"><?=e($schoolName)?> · Build papers from reviewed questions and control result entry and publication.</p></div><?php if(count($schools)>1):?><form method="get"><label for="exam-school">School</label><select id="exam-school" name="school_id" onchange="this.form.submit()"><?php foreach($schools as $s):?><option value="<?=$s['id']?>"<?=(int)$s['id']===$schoolId?' selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></form><?php endif;?></section><div id="exam-status-message" class="notice" role="status" aria-live="polite" hidden></div><section class="note-create"><div class="section-heading"><div><div class="eyebrow">PAPER BUILDER</div><h2 id="exam-form-title">Create examination draft</h2></div></div><form id="exam-form" class="note-form"><input type="hidden" name="action" value="save_exam"><input type="hidden" name="exam_id"><input type="hidden" name="questions" value="[]"><